begin
 if p_key is null then return null; end if;
 if left(p_key,7)='custom:' then return substr(p_key,8); end if;
 item_id := split_part(p_key,' [',1);
 return coalesce(labels->>item_id,initcap(replace(item_id,'_',' '))) || substr(p_key,char_length(item_id)+1);
end;
$function$;
revoke all on function public.captive_kit_label(text) from public,authenticated;

