$function$;
revoke all on function public.captive_skill_label(text) from public,authenticated;

alter table public.captive_proposals drop constraint captive_proposals_message_check;
alter table public.captive_proposals add constraint captive_proposals_message_check check (char_length(message) between 1 and 30000);

do $migration$
declare fn text; definition text; updated text;
begin
 foreach fn in array array['validate_core_captive_roster_proposal','validate_forced_henchman_proposal','validate_companion_proposal','validate_kidnapped_proposal','validate_exchange_proposal'] loop
  select pg_get_functiondef((format('public.%s(public.captive_cases,jsonb,jsonb,jsonb,jsonb)',fn))::regprocedure) into definition;
  updated := replace(definition,
    $$return left(array_to_string(parts, '. ') || '.', 1000);$$,
    $$return array_to_string(parts, '. ') || '.';$$);
  updated := replace(updated,
    $$return left('Exchange of captives. ' || regexp_replace(text_a, '^(Ransom|Released)[^:]*: ', '') || ' In return: ' || regexp_replace(text_b, '^(Ransom|Released)[^:]*: ', ''), 1000);$$,
    $$return 'Exchange of captives. ' || regexp_replace(text_a, '^(Ransom|Released)[^:]*: ', '') || ' In return: ' || regexp_replace(text_b, '^(Ransom|Released)[^:]*: ', '');$$);
  updated := replace(updated,$$string_agg(e.key ||$$,$$string_agg(public.captive_kit_label(e.key) ||$$);
  if fn='validate_core_captive_roster_proposal' then
   updated := replace(updated,
    $$parts := array[label || ': ' || h.name || ' (' || v.name || ') becomes ' || expect_status];$$,
    $$parts := array[label || ': ' || h.name || case when expect_status='active' then ' returns to ' || v.name when expect_status='retired' then ' leaves ' || v.name || ' permanently' else ' is removed from ' || v.name end];$$);
   updated := replace(updated,
    $$k.name, group_unit, coalesce(group_name, h.name)$$,
    $$k.name, case group_unit when 'undead_zombies' then 'Zombie' when 'court_of_pleasures_wretches' then 'Wretch' when 'cursed_cavalcade_captured_thrall' then 'Captured Thrall' else initcap(replace(group_unit,'_',' ')) end, coalesce(group_name, h.name)$$);
  end if;
  if fn='validate_kidnapped_proposal' then
   updated := replace(updated,$$' leaves his warband (retired)'$$,$$' leaves his warband permanently'$$);
   updated := replace(updated,$$array_to_string(kit_keys, ', ')$$,$$(select string_agg(public.captive_kit_label(item), ', ' order by ordinal) from unnest(kit_keys) with ordinality as s(item,ordinal))$$);
   updated := replace(updated,$$array_to_string(victim_skills, ', ')$$,$$(select string_agg(public.captive_skill_label(skill), ', ' order by ordinal) from unnest(victim_skills) with ordinality as s(skill,ordinal))$$);
  end if;
  if updated=definition then raise exception 'Could not locate readable consent insertion points in %',fn; end if;
  execute updated;
 end loop;
end;
$migration$;
